1	// 高层基于冲突的多智能体寻路搜索器 (High-Level Conflict-Based Search, CBS)。
2	//
3	// 对应 Phase 9 (P1)：
4	// 在多智能体路径规划 (MAPF) 中，通过维护两级搜索架构：
5	// - 低层 (Low-Level): 为单车在拓扑网络上搜索满足时空约束的最优路径 (PlanSpaceTimeAStar)
6	// - 高层 (High-Level): 构建约束树 (Constraint Tree, CT)，检测多车两两时空冲突，
7	//   并通过分支向各智能体注入时空约束，搜索全局总代价 (Sum-of-Costs) 最优的无冲突解。
8	//
9	// 冲突类型检测：
10	// 1. 顶点冲突 (Vertex Conflict): 两智能体在同一时间步出现在同一站点
11	// 2. 边冲突 (Edge/Swap Conflict): 两智能体在同一时间步在同一无序边上对向穿行或互换位置
12	// 3. 同向追尾/重叠冲突 (Following/Overlap Conflict): 两智能体在同一时间步同向进入同一物理路段
13	#pragma once
14	
15	#include <cstdint>
16	#include <memory>
17	#include <optional>
18	#include <string>
19	#include <unordered_map>
20	#include <vector>
21	
22	#include "amr_dispatcher_core/catalog/station_catalog.hpp"
23	#include "amr_dispatcher_core/planning/space_time_astar.hpp"
24	
25	namespace amr_dispatcher_core::planning {
26	
27	enum class ConflictType {
28	  kVertex,     // 顶点时空重叠
29	  kEdgeSwap,   // 对向互换穿行
30	  kEdgeFollow  // 同向追尾重叠
31	};
32	
33	// 两智能体之间的时空冲突
34	struct AgentConflict {
35	  ConflictType type = ConflictType::kVertex;
36	  std::string agent_a;
37	  std::string agent_b;
38	  std::string station_u;  // 顶点冲突时的站点，或边冲突时的起点
39	  std::string station_v;  // 边冲突时的终点 (顶点冲突时为空)
40	  int time_step = 0;       // 冲突发生的时间步 (或边冲突起始时步)
41	  int time_step_end = 0;   // 边冲突结束时步
42	};
43	
44	// 单智能体规划输入规范
45	struct CBSAgentSpec {
46	  std::string agent_id;
47	  std::string start_station;
48	  std::string goal_station;
49	  int start_time_step = 0;
50	  double start_time_sec = 0.0;
51	};
52	
53	// CBS 整体请求参数
54	struct CBSRequest {
55	  std::vector<CBSAgentSpec> agents;
56	  double travel_speed_mps = 1.0;
57	  double time_step_duration_sec = 1.0;
58	
59	  // 初始外加约束 (例如环境已有在途车辆占用的时空禁区)
60	  std::vector<VertexConstraint> initial_vertex_constraints;
61	  std::vector<EdgeConstraint> initial_edge_constraints;
62	
63	  // 搜索限制
64	  int max_ct_nodes = 256;         // 最大展开高层约束树节点数
65	  int max_time_steps = 128;       // 单路径最大时间步
66	  int low_level_max_nodes = 2048; // 单次低层 A* 最大展开节点数
67	};
68	
69	// CBS 协同规划结果
70	struct CBSResult {
71	  bool success = false;
72	  std::unordered_map<std::string, TimedPath> solution; // agent_id -> TimedPath
73	  double sum_of_costs = 0.0;
74	  int expanded_ct_nodes = 0;
75	  std::string message;
76	};
77	
78	// 纯函数：多车冲突检测器 (扫描所有两两轨迹，返回发现的首个最早时空冲突)
79	std::optional<AgentConflict> DetectFirstConflict(
80	    const std::unordered_map<std::string, TimedPath>& paths);
81	
82	// 纯函数：高层冲突树搜索 (CBS Solver)
83	CBSResult PlanConflictBasedSearch(
84	    const CBSRequest& request,
85	    const amr_dispatcher_core::catalog::StationCatalog& catalog);
86	
87	}  // namespace amr_dispatcher_core::planning
