1	#include "amr_dispatcher_core/planning/conflict_based_search.hpp"
2	
3	#include <algorithm>
4	#include <queue>
5	#include <unordered_set>
6	
7	namespace amr_dispatcher_core::planning {
8	
9	namespace {
10	
11	// 获取智能体在给定时间步所在的位置（或正穿行的边）
12	struct AgentStepState {
13	  std::string curr_station;
14	  std::string next_station;
15	  bool is_moving = false;
16	  bool is_active = false;
17	};
18	
19	// 获取智能体在给定时间步所在的位置
20	// 若 tick 正好命中路径中某个离散到达点，则返回该点的 station_id (is_moving=false)
21	// 若 tick 处于两点之间行驶，则 is_moving=true
22	AgentStepState GetAgentStateAtTick(const TimedPath& path, int tick) {
23	  AgentStepState state;
24	  if (path.empty()) return state;
25	
26	  if (tick < path.front().time_step || tick > path.back().time_step) {
27	    state.is_active = false;
28	    return state;
29	  }
30	
31	  state.is_active = true;
32	
33	  // 1. 先检查是否精确处于某个航路点或等待点
34	  for (const auto& pt : path) {
35	    if (pt.time_step == tick) {
36	      state.curr_station = pt.station_id;
37	      state.next_station = pt.station_id;
38	      state.is_moving = false;
39	      return state;
40	    }
41	  }
42	
43	  // 2. 处于航段行驶过程中
44	  for (std::size_t i = 0; i + 1 < path.size(); ++i) {
45	    const auto& p1 = path[i];
46	    const auto& p2 = path[i + 1];
47	    if (tick > p1.time_step && tick < p2.time_step) {
48	      state.curr_station = p1.station_id;
49	      state.next_station = p2.station_id;
50	      state.is_moving = true;
51	      return state;
52	    }
53	  }
54	
55	  state.curr_station = path.back().station_id;
56	  state.next_station = state.curr_station;
57	  state.is_moving = false;
58	  return state;
59	}
60	
61	// 高层约束树节点 (CT Node)
62	struct CTNode {
63	  int id = 0;
64	  // 各智能体拥有的时空约束
65	  std::unordered_map<std::string, std::vector<VertexConstraint>> vertex_constraints;
66	  std::unordered_map<std::string, std::vector<EdgeConstraint>> edge_constraints;
67	
68	  std::unordered_map<std::string, TimedPath> solution;
69	  double cost = 0.0; // Sum-of-Costs
70	  std::optional<AgentConflict> first_conflict;
71	
72	  bool operator>(const CTNode& other) const {
73	    if (cost != other.cost) {
74	      return cost > other.cost;
75	    }
76	    return id > other.id; // tie-break
77	  }
78	};
79	
80	}  // namespace
81	
82	std::optional<AgentConflict> DetectFirstConflict(
83	    const std::unordered_map<std::string, TimedPath>& paths) {
84	  if (paths.size() < 2) {
85	    return std::nullopt;
86	  }
87	
88	  // 计算全局最大时间步
89	  int max_t = 0;
90	  for (const auto& [agent, path] : paths) {
91	    if (!path.empty()) {
92	      max_t = std::max(max_t, path.back().time_step);
93	    }
94	  }
95	
96	  // 转换为稳定顺序的向量
97	  std::vector<std::string> agent_ids;
98	  for (const auto& [agent, _] : paths) {
99	    agent_ids.push_back(agent);
100	  }
101	  std::sort(agent_ids.begin(), agent_ids.end());
102	
103	  // 逐时间步扫描冲突（优先发现时间最早的冲突）
104	  for (int t = 0; t <= max_t + 1; ++t) {
105	    for (std::size_t i = 0; i < agent_ids.size(); ++i) {
106	      const auto& a1 = agent_ids[i];
107	      const auto& path1 = paths.at(a1);
108	      const auto state1 = GetAgentStateAtTick(path1, t);
109	
110	      for (std::size_t j = i + 1; j < agent_ids.size(); ++j) {
111	        const auto& a2 = agent_ids[j];
112	        const auto& path2 = paths.at(a2);
113	        const auto state2 = GetAgentStateAtTick(path2, t);
114	
115	        // 仅当两个智能体在时刻 t 均处于各自运行生命周期内时才触发时空冲突
116	        if (!state1.is_active || !state2.is_active) {
117	          continue;
118	        }
119	
120	        // 1. 检查顶点冲突：在整点时间步 t，两智能体同时精确处于站 u（停顿或经过整点）
121	        // 若一方正在沿路段移动 (is_moving=true)，则其正在占用通道，不属于整点站点静止/过站冲突
122	        if (!state1.is_moving && !state2.is_moving) {
123	          if (state1.curr_station == state2.curr_station) {
124	            AgentConflict c;
125	            c.type = ConflictType::kVertex;
126	            c.agent_a = a1;
127	            c.agent_b = a2;
128	            c.station_u = state1.curr_station;
129	            c.time_step = t;
130	            return c;
131	          }
132	        }
133	
134	        // 2. 检查边互换穿行对撞冲突 (Swap Conflict)
135	        // a1: u -> v, a2: v -> u
136	        if (state1.is_moving && state2.is_moving) {
137	          if (state1.curr_station == state2.next_station &&
138	              state1.next_station == state2.curr_station) {
139	            AgentConflict c;
140	            c.type = ConflictType::kEdgeSwap;
141	            c.agent_a = a1;
142	            c.agent_b = a2;
