13	double ComputeHeuristic(const amr_dispatcher_core::catalog::StationCatalog& catalog,
14	                        const std::string& current, const std::string& goal,
15	                        double travel_speed_mps) {
16	  if (current == goal) {
17	    return 0.0;
18	  }
19	  const auto dist = amr_dispatcher_core::catalog::EstimateRouteDistance(catalog, current, goal);
20	  if (!dist.has_value()) {
21	    return 1e6;  // 不可达
22	  }
23	  const double speed = (travel_speed_mps > 0.05) ? travel_speed_mps : 1.0;
24	  return *dist / speed;
25	}
