27	// 内部搜索节点
28	struct AStarNode {
29	  std::string station_id;
30	  int time_step = 0;
31	  double arrival_time_sec = 0.0;
32	  double g_cost = 0.0;
33	  double f_cost = 0.0;
34	  std::shared_ptr<AStarNode> parent = nullptr;
35	  bool is_wait = false;
36	
37	  bool operator>(const AStarNode& other) const {
38	    return f_cost > other.f_cost;
39	  }
40	};
41	
42	std::string StateKey(const std::string& station_id, int time_step) {
43	  return station_id + "@" + std::to_string(time_step);
44	}
45	
46	}  // namespace
47	
48	SpaceTimeAStarResult PlanSpaceTimeAStar(
49	    const SpaceTimeAStarRequest& request,
50	    const amr_dispatcher_core::catalog::StationCatalog& catalog) {
51	  SpaceTimeAStarResult result;
52	
53	  if (request.start_station.empty() || request.goal_station.empty()) {
54	    result.success = false;
55	    result.message = "start or goal station is empty";
56	    return result;
57	  }
58	
59	  // 构建约束快速查找索引
60	  std::unordered_set<std::string> vertex_constraint_set;
61	  for (const auto& vc : request.vertex_constraints) {
62	    if (vc.agent_id.empty() || vc.agent_id == request.agent_id) {
63	      vertex_constraint_set.insert(StateKey(vc.station_id, vc.time_step));
64	    }
65	  }
66	
67	  std::vector<EdgeConstraint> active_edge_constraints;
68	  for (const auto& ec : request.edge_constraints) {
69	    if (ec.agent_id.empty() || ec.agent_id == request.agent_id) {
70	      active_edge_constraints.push_back(ec);
71	    }
72	  }
73	
74	  // 起点自身是否存在顶点约束
75	  if (vertex_constraint_set.count(StateKey(request.start_station, request.start_time_step))) {
76	    result.success = false;
77	    result.message = "start station is blocked by vertex constraint at start_time_step";
78	    return result;
79	  }
