5	namespace amr_dispatcher_core::workflow {
6	
7	namespace {
8	
9	std::string DefaultEdgeIdBuilder(const std::string& u, const std::string& v) {
10	  if (u < v) {
11	    return "route_edge:" + u + "__" + v;
12	  }
13	  return "route_edge:" + v + "__" + u;
14	}
15	
16	std::string DefaultNodeIdBuilder(const std::string& node) {
17	  return "route_node:" + node;
18	}
19	
20	}  // namespace
21	
22	ResourceTimeWindowSet ConvertTimedPathToTimeWindows(
23	    const amr_dispatcher_core::planning::TimedPath& timed_path,
24	    std::chrono::steady_clock::time_point base_time,
25	    double time_step_duration_sec,
26	    const std::function<std::string(const std::string&, const std::string&)>& edge_id_builder,
27	    const std::function<std::string(const std::string&)>& node_id_builder) {
28	  ResourceTimeWindowSet windows;
29	  if (timed_path.empty()) return windows;
30	
31	  const auto edge_builder = edge_id_builder ? edge_id_builder : DefaultEdgeIdBuilder;
32	  const auto node_builder = node_id_builder ? node_id_builder : DefaultNodeIdBuilder;
33	  const double dt = (time_step_duration_sec > 0.05) ? time_step_duration_sec : 1.0;
34	
35	  for (std::size_t i = 0; i < timed_path.size(); ++i) {
36	    const auto& pt = timed_path[i];
37	    // 节点窗口
38	    ResourceTimeWindow nw;
39	    nw.resource_id = node_builder(pt.station_id);
40	    nw.is_intersection = true;
41	    nw.enter = base_time + std::chrono::milliseconds(static_cast<int64_t>(pt.time_step * dt * 1000));
42	    // 节点至少占用一个时步或至下一时步
43	    int next_step = pt.time_step + 1;
44	    if (i + 1 < timed_path.size() && timed_path[i + 1].station_id == pt.station_id) {
45	      next_step = timed_path[i + 1].time_step;
46	    }
47	    nw.exit = base_time + std::chrono::milliseconds(static_cast<int64_t>(next_step * dt * 1000));
48	    windows.push_back(nw);
49	
50	    // 边窗口 (若前往下一不同站点)
51	    if (i + 1 < timed_path.size() && timed_path[i + 1].station_id != pt.station_id) {
52	      const auto& next_pt = timed_path[i + 1];
53	      ResourceTimeWindow ew;
54	      ew.resource_id = edge_builder(pt.station_id, next_pt.station_id);
55	      ew.is_intersection = false;
56	      ew.enter = base_time + std::chrono::milliseconds(static_cast<int64_t>(pt.time_step * dt * 1000));
57	      ew.exit = base_time + std::chrono::milliseconds(static_cast<int64_t>(next_pt.time_step * dt * 1000));
58	      windows.push_back(ew);
59	    }
60	  }
61	
62	  return windows;
63	}
64	
65	CBSCoordinationResult PlanCBSMultiMissionCoordination(
66	    const std::vector<CBSMissionRequest>& requests,
67	    const amr_dispatcher_core::catalog::StationCatalog& catalog,
68	    const TimeSpaceOccupancy& existing_occupancy,
69	    const MotionTimingConfig& timing_config,
70	    std::chrono::steady_clock::time_point now_time) {
71	  CBSCoordinationResult result;
72	  if (requests.empty()) {
73	    result.all_solved = true;
74	    result.message = "no mission requests";
75	    return result;
76	  }
77	
78	  amr_dispatcher_core::planning::CBSRequest cbs_req;
79	  cbs_req.travel_speed_mps = timing_config.cruise_speed_mps;
80	  cbs_req.time_step_duration_sec = 1.0;
81	
82	  const double dt = cbs_req.time_step_duration_sec;
83	
84	  // 1. 将现存在途占用转换为 CBS 初始时空约束 (Fixed Traffic Constraints)
85	  for (const auto& [res_id, entries] : existing_occupancy.by_resource) {
86	    for (const auto& entry : entries) {
87	      if (entry.exit <= now_time) continue; // 已过去的占用忽略
88	
89	      const auto start_offset_ms = std::chrono::duration_cast<std::chrono::milliseconds>(
90	          (entry.enter > now_time) ? (entry.enter - now_time) : std::chrono::milliseconds(0)).count();
91	      const auto end_offset_ms = std::chrono::duration_cast<std::chrono::milliseconds>(
92	          entry.exit - now_time).count();
93	
94	      const int t_start = static_cast<int>(start_offset_ms / (dt * 1000));
95	      const int t_end = static_cast<int>(std::ceil(end_offset_ms / (dt * 1000)));
96	
97	      if (res_id.rfind("route_node:", 0) == 0) {
98	        const std::string node = res_id.substr(11);
99	        for (int t = t_start; t <= t_end; ++t) {
100	          amr_dispatcher_core::planning::VertexConstraint vc;
101	          vc.agent_id = ""; // 对所有新规划 agent 生效
102	          vc.station_id = node;
103	          vc.time_step = t;
104	          cbs_req.initial_vertex_constraints.push_back(vc);
105	        }
106	      } else if (res_id.rfind("route_edge:", 0) == 0) {
107	        const std::string edge_nodes = res_id.substr(11);
108	        auto pos = edge_nodes.find("__");
109	        if (pos != std::string::npos) {
110	          amr_dispatcher_core::planning::EdgeConstraint ec;
111	          ec.agent_id = "";
112	          ec.from_station = edge_nodes.substr(0, pos);
113	          ec.to_station = edge_nodes.substr(pos + 2);
114	          ec.t_start = t_start;
115	          ec.t_end = t_end;
116	          cbs_req.initial_edge_constraints.push_back(ec);
117	        }
118	      }
119	    }
120	  }
121	
122	  // 2. 组装待规划智能体列表
123	  for (const auto& req : requests) {
124	    amr_dispatcher_core::planning::CBSAgentSpec spec;
125	    spec.agent_id = req.mission_id;
126	    spec.start_station = req.start_station;
127	    spec.goal_station = req.goal_station;
128	
129	    const auto start_delay_ms = std::chrono::duration_cast<std::chrono::milliseconds>(
130	        (req.earliest_start > now_time) ? (req.earliest_start - now_time) : std::chrono::milliseconds(0)).count();
131	    spec.start_time_step = static_cast<int>(start_delay_ms / (dt * 1000));
132	    spec.start_time_sec = start_delay_ms / 1000.0;
133	
134	    cbs_req.agents.push_back(spec);
135	  }
136	
137	  // 3. 执行 CBS 搜索
138	  auto cbs_res = amr_dispatcher_core::planning::PlanConflictBasedSearch(cbs_req, catalog);
139	  if (!cbs_res.success) {
140	    result.all_solved = false;
141	    result.message = "CBS failed: " + cbs_res.message;
142	    return result;
143	  }
144	
145	  // 4. 将 CBS 规划解回填并转换为 ResourceTimeWindowSet
146	  result.all_solved = true;
147	  result.message = "all missions coordinated by CBS";
148	
149	  for (const auto& req : requests) {
150	    CBSMissionPlan mplan;
151	    mplan.mission_id = req.mission_id;
152	
153	    auto it = cbs_res.solution.find(req.mission_id);
154	    if (it != cbs_res.solution.end() && !it->second.empty()) {
155	      mplan.success = true;
156	      // 提取拓扑节点路径
157	      for (const auto& pt : it->second) {
158	        if (mplan.path_nodes.empty() || mplan.path_nodes.back() != pt.station_id) {
159	          mplan.path_nodes.push_back(pt.station_id);
160	        }
161	      }
162	      // 转换时空窗口
163	      mplan.time_windows = ConvertTimedPathToTimeWindows(
164	          it->second, now_time, dt, DefaultEdgeIdBuilder, DefaultNodeIdBuilder);
